ee:message.ee:set-payload:
%dw 2.0
ns soap12 http://www.w3.org/2003/05/soap-envelope
output text/xml
var request = payload.pqrMassiveFailure
---
{
  soap12#Envelope @('xmlns:xsi':"http://www.w3.org/2001/XMLSchema-instance", 'xmlns:xsd':"http://www.w3.org/2001/XMLSchema"): {
    soap12#Body: {
      Set_Data_Falla_Masiva @('xmlns':"http://www.etb.com.co/Gateway/MDM_Data_Services"): {
        WSRequestHeader: {
          system: {
            name: request.requestHeader.system.name,
            correlationId: request.requestHeader.system.correlationId,
            processingServer: request.requestHeader.system.processingServer
          },
          property: request.requestHeader.property map ((item, index) -> 
          {
            Property: {
              name: item.name,
              value: item.value
            }
          })
        },
        WSRequestBody: {
          numero_pqr: request.requestBody.pqrNumber,
          tes: request.requestBody.tes,
          mitigado: request.requestBody.mitigado,
          set_type: request.requestBody.operationType,
          cierre1: request.requestBody.cierre1,
          cierre2: request.requestBody.cierre2,
          cierre3: request.requestBody.cierre3,
          fechaSolucion: request.requestBody.fechaSolucion,
          imputabilidad: request.requestBody.imputabilidad,
          respuestaPQR: request.requestBody.respuestaPQR,
          codigoResolucion: request.requestBody.codigoResolucion,
          descripcionResolucion: request.requestBody.descripcionResolucion,
          rowIdActividad: request.requestBody.rowIdActividad,
          estadoActividad: request.requestBody.estadoActividad,
          comentarios: request.requestBody.comentarios
        }
      }
    }
  }
}
